select g.name, count(m.id) members, string_agg(fd.name, ', ' order by m.sort_order) fields from tenant_7d218705360b.field_groups g left join tenant_7d218705360b.field_group_members m on m.field_group_id=g.id left join tenant_7d218705360b.field_definitions fd on fd.id=m.field_definition_id where g.entity_type='PROJECT' or g.name like 'Obs%' or g.name like 'Matter%' group by g.name order by g.name;
